    },
    {
      "stage": 3,
      "name": "unconditional_timer_fb_calls_outside_case_if",
      "description": "No timer function blocks are required. For this FB there are no top-level timer FB calls. Future timer FBs, if added, must be called unconditionally outside CASE/IF constructs."
    },
    {
      "stage": 4,
      "name": "unified_output_assignments",
      "description": "Assign declared outputs exactly once from final scan state: hiAlarm := hiAlarmState; loAlarm := loAlarmState; error := selected error value; status := selected status code. Invalid-configuration scans preserve the previous alarm output states while updating error/status; valid-configuration scans output the newly computed hysteresis alarm states."
    }
  ],
  "formal_assertions": [
    {
      "id": "A_init",
      "formula": "init"
    },
    {
      "id": "A1_badRangePriority",
      "formula": "G((loLevel >= hiLevel) -> (error & status = 16#8001 & hiAlarm = Y(hiAlarm) & loAlarm = Y(loAlarm)))"
    },
    {
      "id": "A2_badWindow",
      "formula": "G(((loLevel < hiLevel) & (hystWindow >= real32(hiLevel - loLevel))) -> (error & status = 16#8002 & hiAlarm = Y(hiAlarm) & loAlarm = Y(loAlarm)))"
    },
    {
      "id": "A3_validClearsError",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0)) -> (!error & status = 0))"
    },
    {
      "id": "A4_highTrigger",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0) & (Value > hiLevel)) -> hiAlarm)"
    },
    {
      "id": "A5_highRelease",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0) & (Value < real32(hiLevel - hystWindow))) -> !hiAlarm)"
    },
    {
      "id": "A6_highHysteresisRetain",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0) & (real32(hiLevel - hystWindow) <= Value) & (Value <= hiLevel)) -> (hiAlarm = Y(hiAlarm)))"
    },
    {
      "id": "A7_lowTrigger",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0) & (Value < loLevel)) -> loAlarm)"
    },
    {
      "id": "A8_lowRelease",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0) & (Value > real32(loLevel + hystWindow))) -> !loAlarm)"
    },
    {
      "id": "A9_lowHysteresisRetain",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0) & (loLevel <= Value) & (Value <= real32(loLevel + hystWindow))) -> (loAlarm = Y(loAlarm)))"
    }
  ]
}

